1	// pm/schedule.js — 排程台账（施工令-040 · Q1 后端半）
2	// 案源：2026-08-11 点名巡礼「监制台看不到后续的队列工作」——「接下来要做什么」此前只活在会话记忆里，
3	// 换会话即失忆，制作人在监制台上看到的永远只有**已经成单**的那几张，队列是空的。
4	// 本模块把「尚未成单的批次计划项」立成系统实体：**计划粒**。
5	//
6	// 三条硬口径（红队 v2 十一杀之后的结论，改一处就是改协议）：
7	//   ① 只追加：事件日志 jsonl，一次写盘 = 一条事件；读取时折叠成现态。**禁覆盖写**——
8	//      台账类的覆盖写吃过亏（pm/ledger 主档损毁案），排程账从设计上就不给覆盖留入口。
9	//   ② CAS：每粒一个版本号，写 API 必须带 预期版本，不符即拒并把现态回给调用方重试。
10	//      单进程内 appendFileSync 本身串行，但「读-改-写」跨请求不串行——不校验版本，
11	//      两个调用方先后读到同一现态、各自转移，后手会静默覆盖先手的意图。
12	//   ③ 状态机严进：计划→起草中→已成单→完成；前置态可撤销；**已成单不可直接撤销**
13	//      （单已经发出去了，撤粒不撤单＝台账与工单池对不上账，须先收回工单）。非法转移一律拒绝**并留痕**。
14	const fs = require('fs');
15	const path = require('path');
16	const crypto = require('crypto');
17	
18	const DIR = (root) => path.join(root, '排程台账');
19	const LOG = (root) => path.join(DIR(root), '排程账.jsonl');
20	
21	// 状态机（唯一实现，API/钩子/迁移三处共读——不许任何一处自己再判一遍）
22	const 转移表 = {
23	  计划: ['起草中', '撤销'],
24	  起草中: ['已成单', '撤销'],
25	  已成单: ['完成'],     // 撤销不在此列：要撤先收回工单（见 转移() 的专项拒因）
26	  完成: [],
27	  撤销: [],
28	};
29	const 状态全集 = Object.keys(转移表);
30	const 终态 = ['完成', '撤销'];
31	const 依赖规则集 = ['全部完成', '任一完成'];
32	const 操作域 = { 登记: ['总监', '项管'], 调整: ['项管', '总监'], 转移: ['总监', '项管', '制作人'] };
33	
34	const nowIso = () => new Date().toISOString();
35	function journal(root, msg) { try { require('../journal').append(root, msg); } catch { /* 无 journal 环境（测试）忽略 */ } }
36	
37	// ---- 事件层（只追加）----
38	// 事件形状：{ 粒ID, 事件类型, 字段变更, 版本号, 时刻, 操作者 }（+ 拒绝事件附 因）
39	function 事件流(root) {
40	  try {
41	    return fs.readFileSync(LOG(root), 'utf8').split(/\r?\n/).filter(Boolean)
42	      .map((l) => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean);
43	  } catch { return []; }
44	}
45	function 写事件(root, e) {
46	  fs.mkdirSync(DIR(root), { recursive: true });
47	  fs.appendFileSync(LOG(root), JSON.stringify(e) + '\n', 'utf8');
48	  return e;
49	}
50	
51	// 折叠：事件流 → 现态表。拒绝事件是**审计痕**，既不改字段也不进版本——
52	// 折叠时整条跳过，否则一次误操作就会把版本号顶高，让所有正在重试的调用方全部 CAS 失败。
53	function 折叠(events) {
54	  const m = new Map();
55	  for (const e of events) {
56	    if (!e || !e.粒ID || e.事件类型 === '拒绝') continue;
57	    const cur = m.get(e.粒ID) || { 粒ID: e.粒ID, 版本号: 0, 登记时刻: e.时刻 || null };
58	    Object.assign(cur, e.字段变更 || {});
59	    cur.粒ID = e.粒ID; // 粒ID 不可变：字段变更里就算混进 粒ID 也覆盖不掉
60	    cur.版本号 = Number.isInteger(e.版本号) ? e.版本号 : cur.版本号 + 1;
61	    cur.更新时刻 = e.时刻 || cur.更新时刻 || null;
62	    cur.末次操作者 = e.操作者 || cur.末次操作者 || null;
63	    m.set(e.粒ID, cur);
64	  }
65	  return m;
66	}
67	
68	// 排序口径唯一：批 → 序 → 题。API 下发即按此序，消费端（Q2 流程页/总览）不必各排各的。
69	const 比序 = (a, b) => String(a.批 || '').localeCompare(String(b.批 || ''), 'zh')
70	  || (Number(a.序) || 0) - (Number(b.序) || 0)
71	  || String(a.题 || '').localeCompare(String(b.题 || ''), 'zh');
72	
73	function 现态(root) { return [...折叠(事件流(root)).values()].sort(比序); }
74	function 取(root, 粒ID) { return 折叠(事件流(root)).get(String(粒ID)) || null; }
75	
76	// 判重键（迁移幂等口径，施工令第 7 条）：来源 + 题。
77	// 不用 批+序：批次表改序是常态（调整 API 就是干这个的），拿会变的字段当身份必然重复迁移。
78	const 判重键 = (x) => `${String(x.来源 || '').trim()}||${String(x.题 || '').trim()}`;
79	
80	// ---- 校验（登记入口的唯一把关处，整批一条不合法则整批不写，同 roster.apply 口径）----
81	function 规范依赖(d) {
82	  if (d == null || d === '') return { 值: [] };
83	  if (!Array.isArray(d)) return { error: '依赖必须是数组' };
84	  const out = [];
85	  for (const it of d) {
86	    if (!it || typeof it !== 'object') return { error: '依赖项必须是 {ref,规则} 对象' };
87	    const ref = String(it.ref || '').trim();
88	    if (!ref) return { error: '依赖项缺 ref（粒ID 或单号）' };
89	    const 规则 = String(it.规则 || '全部完成').trim();
90	    if (!依赖规则集.includes(规则)) return { error: `依赖规则只能是 ${依赖规则集.join('/')}（收到 ${规则}）` };
91	    out.push({ ref: ref.slice(0, 80), 规则 });
92	  }
93	  return { 值: out };
94	}
95	function 规范粒(raw) {
96	  const x = raw || {};
97	  const 批 = String(x.批 ?? '').trim();
98	  const 题 = String(x.题 ?? '').trim();
99	  const 来源 = String(x.来源 ?? '').trim();
100	  if (!批) return { error: '批必填' };
101	  if (!题) return { error: '题必填' };
102	  if (!来源) return { error: '来源必填（文档§引用——判重与追溯都靠它）' };
103	  const 序 = x.序 == null || x.序 === '' ? 0 : Number(x.序);
104	  if (!Number.isInteger(序) || 序 < 0) return { error: `序须为非负整数（收到 ${x.序}）` };
105	  const 状态 = String(x.状态 ?? '计划').trim();
106	  if (!状态全集.includes(状态)) return { error: `未知状态：${状态}（可选 ${状态全集.join('/')}）` };
107	  const dep = 规范依赖(x.依赖);
108	  if (dep.error) return { error: dep.error };
109	  const 单号 = String(x.单号 ?? '').trim();
110	  // 已成单/完成 必须带单号：没有单号的「已成单」是对不上账的账——迁移终态回填走的正是这条路
111	  if (['已成单', '完成'].includes(状态) && !单号) return { error: `状态 ${状态} 必须回填单号` };
112	  let 预估单元 = null;
113	  if (x.预估单元 != null && x.预估单元 !== '') {
114	    预估单元 = Number(x.预估单元);
115	    if (!(预估单元 >= 0) || !Number.isFinite(预估单元)) return { error: `预估单元须为非负数（收到 ${x.预估单元}）` };
116	  }
117	  return {
118	    值: {
119	      批: 批.slice(0, 40), 序, 题: 题.slice(0, 120), 状态,
120	      管线: String(x.管线 ?? '').trim().slice(0, 40) || null,
121	      依赖: dep.值,
122	      池衡建议: String(x.池衡建议 ?? '').trim().slice(0, 60) || null,
123	      预估单元,
124	      来源: 来源.slice(0, 200),
125	      单号: 单号 ? 单号.slice(0, 40) : null,
126	    },
127	  };
128	}
129	
130	// 拒绝留痕（状态机第 3 条「非法转移一律拒绝并留痕」）：审计事件进账 + journal 一行。
131	// 留在账里而不是只留 journal——排程账才是这个实体的事实源，翻它就该看得见谁在什么时候想干什么被拦了。
132	function 拒(root, g, 因, 操作者) {
133	  const 文 = String(因).slice(0, 200);
134	  try {
135	    写事件(root, { 粒ID: g.粒ID, 事件类型: '拒绝', 字段变更: {}, 版本号: g.版本号, 时刻: nowIso(), 操作者: String(操作者 || '').slice(0, 40), 因: 文 });
136	  } catch (e) { console.error('排程账拒绝留痕失败：' + e.message); }
137	  journal(root, `排程台账拒绝 ${g.粒ID}「${g.题 || ''}」：${文}`);
138	  return { ok: false, error: 文, 现态: g };
139	}
140	
141	// CAS 校验（第 4 条）：写 API 的公共前置。冲突不进账（重试是正常流量，不该刷审计），
142	// 但必须把**现态**回给调用方——「拒了」不告诉对方现在是什么样，等于逼它盲猜重试。
143	function 校验版本(g, 预期版本) {
144	  if (预期版本 == null || 预期版本 === '') return { error: '预期版本必填（CAS：写前先读现态，把版本号带回来）' };
145	  const v = Number(预期版本);
146	  if (!Number.isInteger(v)) return { error: `预期版本须为整数（收到 ${预期版本}）` };
147	  if (v !== g.版本号) return { error: `版本冲突：预期 ${v}，现 ${g.版本号}——请按现态重试`, 冲突: true };
148	  return {};
149	}
150	
151	// ---- 写 API ----
152	
153	// 登记（整批）：新粒入账。幂等按 来源+题 判重，重复项跳过并如实回报（迁移重跑靠它）。
154	function 登记(root, 粒们, 操作者, opts = {}) {
155	  if (!Array.isArray(粒们) || !粒们.length) return { ok: false, error: '登记需要非空的计划粒数组' };
156	  const 人 = String(操作者 || '').trim();
157	  if (opts.校验操作域 !== false && !操作域.登记.includes(人)) {
158	    return { ok: false, 越权: true, error: `登记权在 ${操作域.登记.join('/')}（收到「${人 || '空'}」）` };
159	  }
160	  const 已有 = new Map(现态(root).map((g) => [判重键(g), g]));
161	  const 待写 = []; const 跳过 = []; const 错 = [];
162	  粒们.forEach((raw, i) => {
163	    const v = 规范粒(raw);
164	    if (v.error) { 错.push(`第 ${i + 1} 条「${String((raw || {}).题 || '').slice(0, 20)}」：${v.error}`); return; }
165	    const k = 判重键(v.值);
166	    const 命中 = 已有.get(k);
167	    if (命中) { 跳过.push({ 题: v.值.题, 来源: v.值.来源, 已有粒ID: 命中.粒ID }); return; }
168	    已有.set(k, { ...v.值, 粒ID: '(本批)' }); // 同一批里的重复项也算重，否则一次登记就能造出两条同粒
169	    待写.push(v.值);
170	  });
171	  if (错.length) return { ok: false, error: '整批未写入：' + 错.join('；') }; // 整批校验：一条不合法则一条都不落
172	  const 时刻 = nowIso();
173	  const 新增 = 待写.map((g) => {
174	    const 粒ID = crypto.randomUUID();
175	    写事件(root, { 粒ID, 事件类型: '登记', 字段变更: { ...g }, 版本号: 1, 时刻, 操作者: 人 });
176	    return { ...g, 粒ID, 版本号: 1, 登记时刻: 时刻, 更新时刻: 时刻, 末次操作者: 人 };
177	  });
178	  if (新增.length || 跳过.length) {
179	    journal(root, `排程台账登记（${人}）：新增 ${新增.length} 粒${跳过.length ? ` · 判重跳过 ${跳过.length} 粒（来源+题）` : ''}`);
180	  }
181	  return { ok: true, 新增, 跳过 };
182	}
183	
184	// 转移：状态机唯一写口。带 CAS；非法转移拒绝并留痕。
185	function 转移(root, { 粒ID, 目标, 预期版本, 操作者, 单号, 说明 } = {}) {
186	  const g = 取(root, 粒ID);
187	  if (!g) return { ok: false, error: `计划粒不存在：${粒ID}` };
188	  const 人 = String(操作者 || '').slice(0, 40);
189	  const to = String(目标 || '').trim();
190	  if (!状态全集.includes(to)) return 拒(root, g, `未知目标状态：${to || '空'}（可选 ${状态全集.join('/')}）`, 人);
191	  const cas = 校验版本(g, 预期版本);
192	  if (cas.error) return { ok: false, error: cas.error, ...(cas.冲突 ? { 冲突: true } : {}), 现态: g };
193	  // 已成单→撤销 单列一条拒因：这不是"忘了配转移表"，是**业务上必须先收回工单**。
194	  // 只回一句「不合法的转移」，调用方会去改状态机；回这句，他会去收单。
195	  if (g.状态 === '已成单' && to === '撤销') {
196	    return 拒(root, g, `已成单不可直接撤销——先收回对应工单 ${g.单号 || '(未回填)'}，再撤粒`, 人);
197	  }
198	  if (g.状态 === to) return 拒(root, g, `已经是 ${to}，无需转移`, 人);
199	  if (!转移表[g.状态].includes(to)) {
200	    return 拒(root, g, `不合法的转移：${g.状态} → ${to}（${g.状态} 只能去 ${转移表[g.状态].join('/') || '无（终态）'}）`, 人);
201	  }
202	  const 新单号 = String(单号 || '').trim() || g.单号 || null;
203	  if (to === '已成单' && !新单号) return 拒(root, g, '转「已成单」必须回填单号', 人);
204	  const 变更 = { 状态: to };
205	  if (新单号 !== g.单号) 变更.单号 = 新单号;
206	  if (String(说明 || '').trim()) 变更.末次说明 = String(说明).trim().slice(0, 200);
207	  const e = 写事件(root, { 粒ID: g.粒ID, 事件类型: '转移', 字段变更: 变更, 版本号: g.版本号 + 1, 时刻: nowIso(), 操作者: 人 });
208	  journal(root, `排程粒转移 ${g.粒ID}「${g.题}」：${g.状态} → ${to}${变更.单号 ? ` · 单号 ${变更.单号}` : ''}（${人 || '未署名'}）`);
209	  return { ok: true, 粒: { ...g, ...变更, 版本号: e.版本号, 更新时刻: e.时刻, 末次操作者: 人 } };
210	}
211	
212	// 调整（H99 项管域）：改序 / 改依赖 / 改池衡建议。带 CAS。
213	// 只开这三个字段：题/来源是身份（判重键），批/状态各有专路，单号只由钩子回填——
214	// 开成通用 patch 口，台账立刻退化成一张可以随便改的表，事件日志就白留了。
215	function 调整(root, { 粒ID, 预期版本, 序, 依赖, 池衡建议, 操作者, 说明 } = {}, opts = {}) {
216	  const g = 取(root, 粒ID);
217	  if (!g) return { ok: false, error: `计划粒不存在：${粒ID}` };
218	  const 人 = String(操作者 || '').trim();
219	  if (opts.校验操作域 !== false && !操作域.调整.includes(人)) {
220	    return { ok: false, 越权: true, error: `调整权在 ${操作域.调整.join('/')}（H99 项管域，收到「${人 || '空'}」）` };
221	  }
222	  const cas = 校验版本(g, 预期版本);
223	  if (cas.error) return { ok: false, error: cas.error, ...(cas.冲突 ? { 冲突: true } : {}), 现态: g };
224	  if (终态.includes(g.状态)) return 拒(root, g, `终态粒不可调整（当前 ${g.状态}）`, 人);
225	  const 变更 = {};
226	  if (序 != null && 序 !== '') {
227	    const n = Number(序);
228	    if (!Number.isInteger(n) || n < 0) return 拒(root, g, `序须为非负整数（收到 ${序}）`, 人);
229	    变更.序 = n;
230	  }
231	  if (依赖 !== undefined) {
232	    const d = 规范依赖(依赖);
233	    if (d.error) return 拒(root, g, d.error, 人);
234	    if (d.值.some((x) => x.ref === g.粒ID)) return 拒(root, g, '依赖不能指向自己', 人);
235	    变更.依赖 = d.值;
236	  }
237	  if (池衡建议 !== undefined) 变更.池衡建议 = String(池衡建议 || '').trim().slice(0, 60) || null;
238	  if (!Object.keys(变更).length) return { ok: false, error: '调整未给任何可改字段（序/依赖/池衡建议）', 现态: g };
239	  if (String(说明 || '').trim()) 变更.末次说明 = String(说明).trim().slice(0, 200);
240	  const e = 写事件(root, { 粒ID: g.粒ID, 事件类型: '调整', 字段变更: 变更, 版本号: g.版本号 + 1, 时刻: nowIso(), 操作者: 人 });
241	  journal(root, `排程粒调整 ${g.粒ID}「${g.题}」：${Object.keys(变更).filter((k) => k !== '末次说明').join('、')}（${人}）`);
242	  return { ok: true, 粒: { ...g, ...变更, 版本号: e.版本号, 更新时刻: e.时刻, 末次操作者: 人 } };
243	}
244	
245	// ---- H57 挂接钩子（第 6 条）----
246	// 两个钩子都是**系统动作**：CAS 的预期版本由钩子自己读现态取——没有第二个调用方跟它抢同一粒，
247	// 抢的话也该由人那边的 API 拒绝。钩子失败一律只回结果不抛：起草/派发是主干，台账是账，
248	// 账记不上不能把主干带崩（调用点一律 try 包一层，与 pmLedger.event 同待遇）。
249	
250	// 起草落草稿：计划 → 起草中 + 回填单号
251	function 挂钩起草(root, 粒ID, 单号) {
252	  const g = 取(root, 粒ID);
253	  if (!g) return { ok: false, error: `计划粒不存在：${粒ID}`, 无关: true };
254	  return 转移(root, { 粒ID: g.粒ID, 目标: '起草中', 预期版本: g.版本号, 操作者: '系统·H57起草', 单号, 说明: `项管起草落草稿 ${单号 || ''}` });
255	}
256	
257	// 派发：起草中 → 已成单。粒ID 优先，缺则按单号回查（老单 frontmatter 没有 粒ID，认不出就当无关，不猜）。
258	function 挂钩派发(root, 单号, 粒ID) {
259	  let g = 粒ID ? 取(root, 粒ID) : null;
260	  if (!g && 单号) g = 现态(root).find((x) => x.单号 === 单号 && !终态.includes(x.状态)) || null;
261	  if (!g) return { ok: false, error: '无对应计划粒（该单不出自排程台账）', 无关: true };
262	  // 重复派发（收回→重投）不该报错：粒已经是已成单了，这次派发对台账就是个空操作。
263	  if (g.状态 === '已成单') return { ok: true, 幂等: true, 粒: g };
264	  // 补链：粒还停在「计划」（工单是手工起草的，没走 /api/pm/draft），先补一步起草中再成单。
265	  // 宁可补链也不放宽状态机——状态机一旦允许 计划→已成单，「起草中」这一态就名存实亡。
266	  if (g.状态 === '计划') {
267	    const r0 = 转移(root, { 粒ID: g.粒ID, 目标: '起草中', 预期版本: g.版本号, 操作者: '系统·派发补链', 单号, 说明: '派发时发现粒仍在计划态，补起草中一步' });
268	    if (!r0.ok) return r0;
269	    g = 取(root, g.粒ID);
270	  }
271	  return 转移(root, { 粒ID: g.粒ID, 目标: '已成单', 预期版本: g.版本号, 操作者: '系统·派发', 单号: 单号 || g.单号, 说明: `派发 ${单号 || ''}` });
272	}
273	
274	module.exports = {
275	  DIR, LOG, 转移表, 状态全集, 终态, 依赖规则集, 操作域,
276	  事件流, 折叠, 现态, 取, 判重键, 规范粒, 规范依赖,
277	  登记, 转移, 调整, 挂钩起草, 挂钩派发,
278	};
