.nowh { color:var(--now); font-weight:700; }
.fgsum { font-size:12px; color:var(--ink3); white-space:nowrap; }
.fgsum b { font-family:var(--mono); color:var(--ink); font-size:12.5px; }
.fgsum b.s { color:var(--ok); }
.fgboard { position:relative; margin-top:12px; border:1px solid var(--line); border-radius:14px;
  background:var(--card); box-shadow:var(--shadow-sm); overflow:hidden; }
.fgcols { display:grid; grid-template-columns:200px 1fr 1.1fr; border-bottom:1px solid var(--line);
  color:var(--ink3); font-size:11px; letter-spacing:.06em; background:var(--sect); }
.fgcols > div { padding:8px 14px; min-width:0; }
.fglane { border-bottom:1px solid var(--line); }
.fglane:last-child { border-bottom:none; }
.fgrow { display:grid; grid-template-columns:200px 1fr 1.1fr; align-items:stretch; }
/* ---- 管线头 ---- */
.fghead { padding:12px 14px; border-right:1px solid var(--line); min-width:0; }
.fghead b { font-size:13.5px; }
.fghead .sub { color:var(--ink3); font-size:11px; margin-top:2px; overflow:hidden; text-overflow:ellipsis; }
.fghead .pct { font-family:var(--mono); color:var(--ok); font-size:12px; margin-top:6px; }
.fghead .lst { font-family:var(--mono); font-size:10px; font-weight:500; padding:1px 7px; margin-left:6px;
  border-radius:999px; background:var(--chip); color:var(--ink2); }
.fghead .lst.lag { background:var(--gatebg); color:var(--gatetx); border:1px solid var(--gateln); }
/* ---- 两个区：现在（橙）｜接下来 ---- */
.fgzone { padding:10px 12px; position:relative; min-width:0; }
.fgzone.now { background:var(--nowtint); border-left:2px solid var(--now); border-right:1px dashed var(--line); }
.fgidle { color:var(--ink3); font-size:11.5px; padding:14px 2px; text-align:center; }
.fgidle.q { text-align:left; padding:10px 2px; }
/* ---- 条：四型 ---- */
/* 过渡只给 box-shadow，**不给 border-color**：条的边色全是 var(--ok/--danger/--accent) 令牌，
   而带 transition 的属性在自定义属性被换掉（=切主题）时不重算，夜间会留着日间的绿边红边不放
   （2026-08-08 实机抓到：--ok 已是 #2FD6A0，.fgbar.sign 的边还钉在 #0D7A5F）。
   悬停反馈靠 box-shadow + 边色瞬时切换，观感不损，令牌正确性优先。 */
.fgbar { display:flex; align-items:center; gap:8px; margin:4px 0; padding:5px 10px; border-radius:7px;
  background:var(--chip); border:1px solid var(--line); cursor:pointer; min-width:0;
  transition:box-shadow .16s var(--ease-out); }
.fgbar:hover, .fgbar:focus-visible { border-color:var(--accent); box-shadow:var(--shadow-sm); outline:none; }
.fgbar .id { font-family:var(--mono); font-size:11px; color:var(--accent-ink); white-space:nowrap; }
.fgbar .t { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; flex:1 1 0; width:0; min-width:0; font-size:12.5px; } /* width:0 同病同修，见 .prow .pv 上方注释 */
.fgbar .st { font-size:10px; padding:1px 7px; border-radius:999px; white-space:nowrap; color:var(--ink2); background:var(--we); }
.fgbar .deps { font-family:var(--mono); font-size:10px; color:var(--ink3); white-space:nowrap; }
.fgbar .mile { font-size:10px; color:var(--now); white-space:nowrap; font-weight:600; }
/* 在做：实心 + 百分比（百分比是本视图唯一的实时数，给它 mono 与最强字重） */
.fgbar.doing { border-color:var(--accent); background:var(--accenttint); }
.fgbar.doing .pp { font-family:var(--mono); color:var(--ink); font-size:12.5px; font-weight:700; white-space:nowrap; }
/* 字号地板 10px（W32 补巡 · 施工令-030）：这个 % 号原是 9px，860 下已经糊成一团灰点。
   只抬到地板值，不动它在 .pp 里的从属关系（主角还是数字本身）。 */
.fgbar.doing .pp small { font-size:10px; font-weight:500; color:var(--ink3); margin-left:1px; }
.fgbar.doing .st { color:var(--accent-ink); background:transparent; border:1px solid var(--accent-ink); }
.fgbar.doing.nosess { border-style:dashed; }
.fgbar.doing.nosess .st { color:var(--gatetx); border-color:var(--gateln); background:var(--gatebg); }
/* 排队：虚框 */
.fgbar.queue { background:transparent; border-style:dashed; }
.fgbar.queue .st { color:var(--ink3); background:transparent; border:1px solid var(--line); }
.fgbar.queue.ready { border-style:solid; border-color:var(--accent); box-shadow:0 0 0 2px var(--accent-glow); }
.fgbar.queue.ready .st { color:var(--accent-ink); border-color:var(--accent-ink); }
.fgbar.blocked .st { color:var(--danger); border-color:var(--danger); background:var(--dangerbg); }
/* 待判官接手（施工令-038）：委托待验收但判官会话还没起——闸门色，与 .doing.nosess 同源语义
   （"会话没起来"），虚框表明在排队。三个令牌两主题各有一份（:root 暖纸 / html[data-theme="glass"] 玻璃），
   实测 paper #7A5A1E on #FDF3E3、glass #E8B45A on 半透明琥珀，不写死色值。 */
.fgbar.queue.wait .st { color:var(--gatetx); border-color:var(--gateln); background:var(--gatebg); }
/* 签字位：绿框常驻——制作人的活永远不许被别的条盖过去 */
.fgbar.sign { border-color:var(--ok); background:var(--okbg); }
.fgbar.sign .st { color:var(--ok); border:1px solid var(--okln); background:transparent; font-weight:700; }
/* 卡住：红 */
.fgbar.stuck { border-color:var(--danger); background:var(--dangerbg); }
.fgbar.stuck .st { color:var(--danger); border:1px solid var(--danger); background:transparent; font-weight:600; }
/* ---- 沉淀抽屉：折叠条（四类分计数）+ 展开列表 ---- */
.fgfold { display:flex; align-items:center; gap:4px; flex-wrap:wrap; margin-top:6px; padding-top:6px;
  border-top:1px dashed var(--line); font-size:11px; }
.fgfold .fgfk { color:var(--ink3); margin-right:2px; }
.fgfold .fgdot { color:var(--ink3); font-style:normal; opacity:.6; }
.fgcat { font:inherit; font-size:11px; color:var(--ink3); background:transparent; border:1px solid transparent;
  border-radius:999px; padding:1px 8px; cursor:pointer; min-height:22px; }

