const 令名 = /^施工令-(\d+)(?:-(.*))?\.md$/;
const 回执名 = (n) => `回执-${n}.md`;

const iso = (p) => { try { return fs.statSync(p).mtime.toISOString(); } catch { return ''; } };

// 读工程队卡：返回 {施工令,名称,状态,更新时间} 或 null
