  const qrow = (name, l) => {
    const hot = l && l.locked;
    const staleTag = l && l.陈旧 && l.更新于 ? `（${new Date(l.更新于).toTimeString().slice(0, 5)} 读数）` : '';
    const wins = l && Array.isArray(l.窗口) ? l.窗口 : null;
