    <p class="cred-sub">订阅登录归各 CLI 保管 · API key 由监制台加密托管，绝不入配置文件</p>
    ${订阅行('claude', d.订阅.claude)}
    ${订阅行('codex', d.订阅.codex)}
    ${d.托管.length ? d.托管.map(托管行).join('') : '<p class="cred-empty">尚未托管任何 key</p>'}
