      <button class="btn xs" onclick="credsAdd()">＋ 添加 key</button>
      <button class="btn xs" onclick="credsLoad()">重新检测</button>
      ${d.可加密 ? '' : '<span class="err" style="font-size:12px">DPAPI 不可用，无法保存 key</span>'}
      <span class="grow"></span>
