  ];
  const inboxHtml = inbox.map((r) => `<div class="inbox-row card" onclick="location.hash='#/t/${r.id}'" tabindex="0" role="button"
      onkeydown="if(event.key==='Enter'){location.hash='#/t/${r.id}'}">
