        <button class="btn h32" onclick="wkCdCancel()">取消</button><span class="cd-sig">将记作 制作人</span></div></div>` : '');
  const 加钮 = (锚) => (ed && wkState.cdNew !== 锚 ? `<button class="btn h32 cd-add" onclick="wkCdNew('${qesc(锚)}')">＋ 加一块</button>` : '');
  const 体 = 块.map((b) => {
