  }).join('');
  // 策划案专属：定案分层（施工令-020）——组由后端 docs.js 定（doc.组），前端只按组画。
  // 定案/草案（无状态标注默认归此）/决策记录 三组常驻，空组也留头显示 0，让「还没有定案」一眼可见。
  const GRP = [['定案', '📗', '已拍板，可作为下游依据'], ['草案', '📝', '在写或未标状态——不得当依据用'], ['决策记录', '🗳', '怎么定的：访谈/评审/裁决留痕']];
