function dotCls(r) { return 'dot ' + (r.运行 ? 'on live' : 'off'); }
// 执行器副标题：运行即实弹（H81），只补一句执行中清单
// 施工令-012：逐单号清单长度随并发无上界增长，会把参数卡撑破（巡礼 P2-2）——超 3 张收敛成「+N」，
// 全量清单挂 title 悬停可查（runMetaFull）。
function runIds(r) { return ((r && r.执行中) || []).map((x) => x.id); }
function runMeta(r) {
  const ids = runIds(r);
