    const arb = fm.代裁 ? `<span class="pill sm ${fm.代裁.结论 === '给方向' ? 'ok' : 'mut'}">代裁 · ${esc(fm.代裁.结论)}</span>` : '';
    const dirHtml = dirs.length ? dirs.map((p) => {
      const nl = p.indexOf('\n');
