  };
  setTimeout(() => { fillGates().catch(() => { /* 保持占位 */ }); }, 0);
  pollLoop('ov-quota', 5000, fillGates);
  // 就绪灯：就绪=安静文字；降级/阻断=色底胶囊+同色呼吸灯（A 方案，呼吸=需要注意的既有灯语）
  const fillEnv = async () => {
