  for (const e of evAll.filter((x) => new Date(x.t) >= today && x.类型 !== '巡检')) cnt[e.类型] = (cnt[e.类型] || 0) + 1; // 巡检心跳不入今日概括
  const digest = Object.entries(cnt).map(([k, v]) => k + ' ' + v).join(' · ') || '今日无动作';
  const working = d.作业;
