  // 参照 022 的 nosess 同步先例：首屏与轮询同一口径，谁都不许自己改口。
  const sig = (d) => (d.在跑 || []).map((r) => r.id + ':' + r.state + ':' + (r.有会话 ? 1 : 0)).sort().join(',');
  const sig0 = sig(ag);
  pollLoop('fg-board', 15000, async () => {
