// 显示名：一眼知道现在到底在干什么（超时态自带盯守说明）
function 显示名(阶段, 超时) {
  if (阶段 === '执行') return 超时 ? '执行超预估 · 软超时盯守中' : '执行中';
  if (阶段 === '领单') return '衔接中';
  if (阶段 === '质检') return '质检中';
  if (阶段 === '初检') return '初检中 · 格式规范';
  if (阶段 === '核查') return '核查中 · 深检';
  if (阶段 === '你验收') return '待你验收';
  if (阶段 === '仲裁') return '仲裁中';
  if (阶段 === '定夺') return '待定夺';
  if (阶段 === '落袋') return '已落袋';
  return 阶段 || '—';
}

// 无在跑会话时，按目录状态定位阶段（目录态是兜底，现场态优先）
function 状态阶段(state, 委托, 初检已过) {
