// 沉淀抽屉：点某一类只展开该类（置灰列表，点条进详情）；再点同一类收起。
// 不走 route() 重画——整页重取四个接口只为展一个抽屉太贵，且会把 15s 活体轮询打断重挂。
window.fgDrawer = (key, cat) => {
  const box = $('fgd-' + key); if (!box) return;
