  const rows = p ? d.明细.filter((r) => (r.项目 || projDefault()) === p) : d.明细;
  const o = d.总览;
  const stat = (l, v, c) => `<div class="grp"><span class="lbl">${l}</span><span class="num ${c || ''}">${v}</span></div>`;
