    stat('完成', o.完成), stat('归档', o.已归档), stat('实际工时', o.实际h合计 + 'h'),
    stat('实耗/预估', o.预估偏差pct == null ? '—' : o.预估偏差pct + '%', o.预估偏差pct > 150 ? 'err' : o.预估偏差pct != null && o.预估偏差pct <= 110 ? 'okc' : ''), // 100=踩点 <100=省 >150=严重超（旧名「预估偏差」误导）
    stat('自修轮次', o.自修总轮, o.自修总轮 ? 'warnc' : ''),
