    // 一轮回执 → 一屏四件套。解析口径与改版前一字未动，只是从「只解析最新一轮」
    // 改成「每轮各解析一份」，好让下面按轮出页签。
    const 轮Html = ({ 段, 轮 }) => {
      const secs = { 验收步骤: '', 做了什么: '', 'QA 章节': '', 实际消耗: '', 异议: '' };
