  const kidsTxt = (c.父子.子 || []).map((x) => `<a href="#/t/${x.id}" style="color:var(--accent-ink)">${esc(x.id)}</a>(${esc(x.state)})`).join('、');
  // ---- 子单层级一览（施工令-028：树形退役，这张表是它唯一不可替代的那半）----
