// 源文档写法宽松：整路径 / 尾部路径 / 纯文件名（可省 .md）/ 标题——依次匹配，都不中就当纯文本
function docMatch(idx, s) {
  const k = String(s).replace(/^\.\//, '').toLowerCase();
