  const 深 = {};
  const deep = (id, g) => {
    if (深[id] != null) return 深[id];
    深[id] = 0;
    const t = byId[id];
    if (!t || g > 30) return 0;
    const ds = depsOf(t);
    深[id] = ds.length ? Math.max(0, ...ds.map((d) => deep(d, g + 1) + 1)) : 0;
