    return `<div class="emptycard" style="margin-top:30px"><h5>还没有管线，也没有工单</h5>
      <p>先在 <a href="#/params" style="color:var(--accent-ink)">⚙ 参数</a> 开一条管线（H51 人闸），或直接 <a href="#/draft" style="color:var(--accent-ink)">起草工单</a>——
