  // 用闸门色的 .st（与 doing.nosess 同源语义：会话没起来），虚框表明它在排队等判官。
  const waitBar = (t) => bar(t, 'queue wait', '<span class="st">待判官接手</span>');
  const stuckBar = (t) => bar(t, 'stuck', `<span class="st">${esc(t.state)}${t.自修次数 ? ' ×' + t.自修次数 : ''}</span>`);
  const queueBar = (t) => {
