  // 它还没有工单，点它跳详情会 404。点/悬浮给的是制作人真正会问的两件事：这条哪来的、要多久。
  const planTip = (c) => `planTip('${qesc(c.粒ID || '')}')`;
  const planBar = (c) => `<div class="fgbar queue plan" onclick="${planTip(c)}" tabindex="0" role="button"
      onkeydown="if(event.key==='Enter'){${planTip(c)}}" title="${esc(c.提示)}"
      aria-label="计划粒 ${esc(c.题)}（尚未成单）">
      <span class="id">${esc(c.批)}${c.序 ? '·' + c.序 : ''}</span><span class="t">${esc(c.题)}</span>
      <span class="plb">${esc(c.徽章)}</span>
