  const sameDay = d0.toDateString() === new Date().toDateString();
  return sameDay ? `${p2(d0.getHours())}:${p2(d0.getMinutes())}`
    : `${p2(d0.getMonth() + 1)}-${p2(d0.getDate())} ${p2(d0.getHours())}:${p2(d0.getMinutes())}`;
}
