t('摘要 × 完成：不计', () => { assert.equal(摘([粒('完成')]).接下来, 0); });

t('摘要 × 撤销：不计', () => { assert.equal(摘([粒('撤销')]).接下来, 0); });

// ================= 消费③ 晨晚报切片（5 态）=================
