t('切片 × 撤销：当日撤销 → 进变更（今天砍了什么也得报，不许静默消失）', () => {
  assert.deepEqual(切片今日([粒('撤销')]).变更.map((c) => c.状态), ['撤销']);
});

// ================= 分流与边界 =================
t('Q 队列（批无管线）不进管线行，落「监制台维护队列」', () => {
  const r = V.流程页([粒('计划', { 粒ID: 'g-q', 批: 'Q队列', 序: 2, 题: '排程台账后端', 管线: null }), 粒('计划')]);
