8	
9	const T0 = Date.parse('2026-08-06T10:00:00.000Z');
10	const 分 = (n) => T0 + n * 60000;
11	
12	t('阶段锚点：领单 5 / 执行起 5 / 质检起 60 / 初检起 75 / 核查起 80 / 落袋 100', () => {
13	  const base = { 预计时间: '', 阶段起时: null, now: T0 };
14	  assert.equal(progress.compute({ ...base, state: '在途', kind: null }).百分比, 5, '领单锚点 5%');
15	  assert.equal(progress.compute({ ...base, state: '在途', kind: '执行' }).百分比, 5, '执行段起点 5%');
16	  assert.equal(progress.compute({ ...base, state: '质检', kind: '质检' }).百分比, 60, '质检段起点 60%');
17	  assert.equal(progress.compute({ ...base, state: '待验收', kind: '初检' }).百分比, 75, '初检段起点 75%');
18	  assert.equal(progress.compute({ ...base, state: '待验收', kind: '代核' }).百分比, 80, '核查段起点 80%');
19	  assert.equal(progress.compute({ ...base, state: '完成' }).百分比, 100, '真落袋才 100%');
20	});
21	
22	t('阶段内插值：执行跑到预估一半 → 5 + 55×0.5（设计稿口径复核）', () => {
23	  const r = progress.compute({ state: '在途', kind: '执行', 预计时间: '0.5', 阶段起时: new Date(T0).toISOString(), now: 分(15) });
