27	  const a = progress.compute({ state: '在途', kind: '执行', 预计时间: '0.5', 阶段起时: new Date(T0).toISOString(), now: 分(20.1) });
28	  assert.equal(a.百分比, 42, '设计稿状态 A 的 42% 对得上');
29	  // 设计稿状态 B：核查段内 47% → 87%
30	  const b = progress.compute({ state: '待验收', kind: '代核', 预计时间: '1', 阶段起时: new Date(T0).toISOString(), now: 分(28.2) });
