const 分 = (n) => T0 + n * 60000;
const 折 = { 时间折算: true }; // 旧时间口径：显式开才生效

t('阶段锚点：领单 5 / 执行起 5 / 质检起 60 / 初检起 75 / 核查起 80 / 落袋 100', () => {
  const base = { 预计时间: '', 阶段起时: null, now: T0 };
