  assert.equal(progress.compute({ state: '在途', kind: '执行', 预计时间: '0.5', 阶段起时: new Date(T0).toISOString(), now: 分(240), ...折 }).百分比, 60);
});

t('QA 关跳过质检段：执行 5→75%，分段条里没有质检', () => {
