  assert.equal(r.百分比, 75, 'QA 关时执行段上限 75%');
  assert.deepEqual(r.段.map((s) => s.名), ['领单', '执行', '初检', '核查', '落袋']);
  const on = progress.compute({ state: '在途', kind: '执行', QA: '开', 预计时间: '1', 阶段起时: new Date(T0).toISOString(), now: 分(60), ...折 });
