    const wins = l && Array.isArray(l.窗口) ? l.窗口 : null;
    const bars = wins
      ? (wins.length ? wins.map((w) => qbarLine(esc(w.label), w.pct, !!w.已越)).join('') : qbarLine('窗口', null, false))
