      // 一律补末尾 8 行原文——宁可给制作人原文，也不给他一屏破折号。
      const 标准 = !!(secs.做了什么 && secs.做了什么.trim());
      const 有货 = Object.entries(secs).filter(([, v]) => v && v.trim());
