        <span class="subnote" style="margin-left:8px">${d.产出.来源 === '结构化' ? '回执产出章节' : '从回执正文解析'} · 点击调起本机查看</span>
        ${d.产出.产出.map((a) => `<div class="prow" style="margin-top:8px">
