// 全量跑一遍 package.json 的 test 链，逐项报结果（npm 在本会话被拦，改由 node 直驱）
const { execFileSync } = require('child_process');
const fs = require('fs');
const path = require('path');
const dir = 'D:/GitHub/Ticketflow/apps/studio';
const chain = JSON.parse(fs.readFileSync(path.join(dir, 'package.json'), 'utf8')).scripts.test
  .split('&&').map((s) => s.trim().replace(/^node\s+/, '')).filter(Boolean);
let bad = 0;
for (const f of chain) {
  try {
    const out = execFileSync(process.execPath, [f], { cwd: dir, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    const last = out.trim().split(/\r?\n/).pop();
    console.log(`OK   ${f}  —— ${last}`);
  } catch (e) {
    bad++;
    console.log(`FAIL ${f}`);
    console.log(String((e.stdout || '') + (e.stderr || '')).trim().split(/\r?\n/).slice(-12).join('\n'));
  }
}
console.log(bad ? `\n失败 ${bad} 个测试文件` : `\n全链绿：${chain.length} 个测试文件`);

