// 无浏览器渲染冒烟：把 public/app.js 丢进 vm 沙盒（最薄的 DOM 桩），真调 viewFlow()/viewOverview()，
// 数据走真 server（桩台模式）。目的：抓模板级低级错误（未定义变量、拼错的字段、空态分支炸掉），
// 这类错在纯函数测试里照不出来。
const fs = require('fs');
const vm = require('vm');
const path = require('path');
const { spawn } = require('child_process');
const dir = 'D:/GitHub/Ticketflow/apps/studio';
const { makeRoot, seed } = require(path.join(dir, 'test/helper'));
const S = require(path.join(dir, 'lib/pm/schedule'));

const root = makeRoot();
const r = S.登记(root, [
  { 批: '批C', 序: 1, 题: '汉代地图 面单一', 来源: '总清单.md §3 批C', 管线: 'P-3', 预估单元: 2 },
  { 批: '批C', 序: 2, 题: '汉代地图 面单二', 来源: '总清单.md §3 批C', 管线: 'P-3' },
  { 批: 'Q队列', 序: 1, 题: '排程台账 B 接线', 来源: '巡礼报告 §六 Q2', 预估单元: 1 },
], '总监');
if (!r.ok) throw new Error(r.error);
seed(root, '待验收', { id: 'TK-901', title: '等你签的单', 验收方式: '保留' });
seed(root, '在途', { id: 'TK-902', title: '正在做的单', 主办: '程序-A', 领单时间: new Date().toISOString() });

const PORT = 4292;
const srv = spawn(process.execPath, ['server.js'], {
  cwd: dir, env: { ...process.env, STUDIO_ROOT: root, STUDIO_PORT: String(PORT), STUDIO_STUB: '1' },
  stdio: ['ignore', 'pipe', 'pipe'],
});
srv.stderr.on('data', (b) => process.stderr.write('[srv] ' + b));

const 元素桩 = () => new Proxy({ dataset: {}, classList: { toggle() {}, add() {}, remove() {}, contains: () => false },
  style: {}, innerHTML: '', textContent: '', title: '', appendChild() {}, remove() {}, closest: () => null,
  querySelectorAll: () => [], addEventListener() {}, getElementsByTagName: () => [] }, {
  get: (t, k) => (k in t ? t[k] : (typeof k === 'string' && /^on/.test(k) ? null : undefined)),
  set: (t, k, v) => { t[k] = v; return true; },
});

(async () => {
  for (let i = 0; i < 60; i++) {
    try { await fetch(`http://127.0.0.1:${PORT}/api/board`); break; } catch { await new Promise((s) => setTimeout(s, 250)); }
  }
  const sandbox = {
    console, setTimeout, clearTimeout, setInterval, clearInterval, Date, Math, JSON, CSS: { escape: (s) => s },
    fetch: (p, o) => fetch(`http://127.0.0.1:${PORT}${p}`, o),
    localStorage: { getItem: () => null, setItem() {}, removeItem() {} },
    location: { hash: '#/flow', href: '' },
    history: { replaceState() {} },
    document: { getElementById: () => null, querySelectorAll: () => [], querySelector: () => null,
      createElement: 元素桩, body: 元素桩(), documentElement: 元素桩(), addEventListener() {}, title: '' },
    navigator: { userAgent: 'node' },
  };
  sandbox.window = sandbox;
  sandbox.globalThis = sandbox;
  vm.createContext(sandbox);
  vm.runInContext(fs.readFileSync(path.join(dir, 'public/app.js'), 'utf8'), sandbox, { filename: 'app.js' });

  const 查 = (名, html, 必含) => {
    const 缺 = 必含.filter((s) => !html.includes(s));
    console.log(`${缺.length ? '✗' : '✓'} ${名}（${html.length} 字符）${缺.length ? ' 缺：' + 缺.join('、') : ''}`);
    if (缺.length) process.exitCode = 1;
  };
  const flow = await sandbox.viewFlow();
  查('流程页渲染', flow, ['fgbar queue plan', '汉代地图 面单一', '>计划<', '监制台维护队列', '排程台账 B 接线', '2 单元', 'lg-plan']);
  console.log('  计划条样例：' + (flow.match(/<div class="fgbar queue plan"[\s\S]{0,420}?<\/div>/) || ['(未匹配)'])[0].replace(/\s+/g, ' ').slice(0, 380));
  const ov = await sandbox.viewOverview();
  查('总览渲染', ov, ['id="ov-sched"']);
  await new Promise((s) => setTimeout(s, 600)); // 等横幅那一发异步填充跑完（真打接口）
  // 直接验横幅 HTML 组装（fillSched 内联在 viewOverview 里，这里复算一遍同一份数据）
  const s = await (await fetch(`http://127.0.0.1:${PORT}/api/schedule/摘要`)).json();
  console.log('  横幅文案：' + s.文);
  const pct = sandbox.pctHtml({ id: 'TK-902', 有会话: true, 环节起时: new Date(Date.now() - 29 * 60000).toISOString(),
    领单时间: new Date(Date.now() - 29 * 60000).toISOString(),
    进度: { 百分比: 28, 阶段名: '执行中', 打点: { k: 3, n: 7 }, 预估分钟: 60, 来源: '打点', 锚点: 5, 段: [] } });
  查('在途卡右列', pct, ['28<small>%</small>', '会话打点 3/7', '已跑', '预估', '（时长）']);
  console.log('  右列：' + pct.replace(/\s+/g, ' ').slice(0, 320));
  const pct2 = sandbox.pctHtml({ id: 'TK-903', 有会话: true, 环节起时: new Date(Date.now() - 29 * 60000).toISOString(),
    进度: { 百分比: 5, 阶段名: '执行中', 打点: null, 预估分钟: 60, 来源: '锚点', 锚点: 5, 段: [] } });
  查('在途卡右列 · 无打点', pct2, ['5<small>%</small>', '阶段锚点', '不按耗时折算']);
  srv.kill();
})().catch((e) => { console.error(e); srv.kill(); process.exitCode = 1; });

