// 施工令-041 真跑冒烟：起真 server（桩台模式 STUDIO_STUB=1，派发面硬关、零计费），
// 打三条新读口 + /api/crew，验证中文动作名路由真的能通（040 踩过「中文字面量路由一律 404」）。
const path = require('path');
const { spawn } = require('child_process');
const dir = 'D:/GitHub/Ticketflow/apps/studio';
const { makeRoot, seed } = require(path.join(dir, 'test/helper'));
const S = require(path.join(dir, 'lib/pm/schedule'));

const root = makeRoot();
// 计划粒：两条管线粒（其一转起草中）+ 一条 Q 队列粒（无管线）+ 一条已成单粒（不该出现在流程页）
const r = S.登记(root, [
  { 批: '批C', 序: 1, 题: '汉代地图 面单一', 来源: '总清单.md §3 批C', 管线: 'P-3', 预估单元: 2 },
  { 批: '批C', 序: 2, 题: '汉代地图 面单二', 来源: '总清单.md §3 批C', 管线: 'P-3', 预估单元: 3 },
  { 批: 'Q队列', 序: 1, 题: '排程台账 B 接线', 来源: '巡礼报告 §六 Q2' },
  { 批: '批B', 序: 9, 题: '已经成单的活', 来源: '总清单.md §3 批B', 管线: 'P-3', 状态: '已成单', 单号: 'TK-127' },
], '总监');
if (!r.ok) throw new Error('登记失败：' + r.error);
const 起草粒 = r.新增[1];
const m = S.转移(root, { 粒ID: 起草粒.粒ID, 目标: '起草中', 预期版本: 起草粒.版本号, 操作者: '总监', 单号: 'TK-140' });
if (!m.ok) throw new Error('转移失败：' + m.error);
seed(root, '待验收', { id: 'TK-901', title: '等你签的单' });
seed(root, '待定夺', { id: 'TK-902', title: '等你拍板的单' });

const PORT = 4291;
const srv = spawn(process.execPath, ['server.js'], {
  cwd: dir, env: { ...process.env, STUDIO_ROOT: root, STUDIO_PORT: String(PORT), STUDIO_STUB: '1' },
  stdio: ['ignore', 'pipe', 'pipe'],
});
srv.stderr.on('data', (b) => process.stderr.write('[srv] ' + b));

const get = async (p) => {
  const res = await fetch(`http://127.0.0.1:${PORT}${p}`);
  return { 状态码: res.status, 体: await res.json() };
};
const 等起 = async () => {
  for (let i = 0; i < 60; i++) {
    try { await fetch(`http://127.0.0.1:${PORT}/api/board`); return true; } catch { await new Promise((s) => setTimeout(s, 250)); }
  }
  return false;
};

(async () => {
  if (!await 等起()) throw new Error('server 起不来');
  console.log('临时仓：' + root + '\n');
  for (const p of ['/api/schedule/流程', '/api/schedule/摘要', '/api/schedule/切片?日=today', '/api/schedule/切片?上限=1', '/api/schedule/瞎写的', '/api/crew']) {
    const r2 = await get(p);
    console.log(`GET ${p}  → ${r2.状态码}`);
    console.log(JSON.stringify(r2.体, null, 1).split('\n').slice(0, 40).join('\n') + '\n');
  }
  srv.kill();
  process.exit(0);
})().catch((e) => { console.error(e); srv.kill(); process.exit(1); });

